using System.Globalization;
using System.Reflection;
using System.Text;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using System.Windows.Media;
using Aksara.Contracts;
using Aksara.Desktop.Services;

namespace Aksara.Desktop.Views;

public enum InventoryReportKind
{
    RetailPrices, TierPrices, CompletePrices, PriceAnalysis, Labels,
    PurchasePriceHistory, PurchaseReturnPriceHistory, SalePriceHistory, SaleReturnPriceHistory, StandardCostHistory,
    Transactions, Transfers, AllAdjustments, OpeningBalance, Adjustments, StockCounts, MbapSends, MbapReceives,
    StockCard, StockCardValue, Valuation, ValuationNoCost, MinimumStock, MaximumStock, DailyEndingStock, DailyOutbound, Turnover, StockLimits
}

public sealed class InventoryReportView : UserControl
{
    private static readonly CultureInfo IndonesianCulture = CultureInfo.GetCultureInfo("id-ID");
    private readonly AksaraApiClient _api = AksaraApiClient.Shared; private readonly InventoryReportKind _kind;
    private readonly DatePicker _from = new() { SelectedDate = new DateTime(DateTime.Today.Year, DateTime.Today.Month, 1), Width = 125 }; private readonly DatePicker _to = new() { SelectedDate = DateTime.Today, Width = 125 };
    private readonly TextBox _query = new() { MinWidth = 210 }; private readonly ComboBox _warehouse = new() { Width = 150, DisplayMemberPath = "Name", SelectedValuePath = "Code" };
    private readonly DataGrid _grid = new() { AutoGenerateColumns = true, IsReadOnly = true, CanUserAddRows = false, RowHeight = 24, ColumnHeaderHeight = 28 }; private readonly TextBlock _status = new() { VerticalAlignment = VerticalAlignment.Center };
    public event EventHandler? CloseRequested; public string ReportTitle => TitleFor(_kind);
    public InventoryReportView(InventoryReportKind kind) { _kind = kind; ReportGridTools.ConfigureScrollableReportGrid(_grid); _grid.AutoGeneratingColumn += FormatGeneratedColumn; _grid.AutoGeneratedColumns += (_, _) => SizeGeneratedColumns(); Content = Build(); Loaded += async (_, _) => { await LoadWarehousesAsync(); await ReloadAsync(); }; }
    private UIElement Build()
    {
        var root = new Grid { Margin = new Thickness(6), Background = Brushes.White }; root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); root.RowDefinitions.Add(new RowDefinition()); root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
        root.Children.Add(new Border { Background = Brush("#E8EDF3"), BorderBrush = Brush("#B8C4CF"), BorderThickness = new Thickness(1), Padding = new Thickness(10, 7, 10, 7), Child = new TextBlock { Text = ReportTitle.ToUpperInvariant(), FontSize = 14, FontWeight = FontWeights.Bold, Foreground = Brush("#183B56") } });
        var filters = new WrapPanel { Margin = new Thickness(0, 6, 0, 6), VerticalAlignment = VerticalAlignment.Center }; filters.Children.Add(Label("Periode")); filters.Children.Add(_from); filters.Children.Add(Label("s/d")); filters.Children.Add(_to); filters.Children.Add(Label("Gudang")); filters.Children.Add(_warehouse); filters.Children.Add(Label("Cari")); filters.Children.Add(_query); var show = Button("Tampilkan"); show.Click += async (_, _) => await ReloadAsync(); filters.Children.Add(show); var copy = Button("Salin CSV"); copy.Click += (_, _) => CopyCsv(); filters.Children.Add(copy); var excel = Button("Excel"); excel.Click += (_, _) => ReportGridTools.ExportDataGridToExcel(_grid, ReportTitle); filters.Children.Add(excel); var print = Button("Cetak"); print.Click += (_, _) => Print(); filters.Children.Add(print); Grid.SetRow(filters, 1); root.Children.Add(filters);
        Grid.SetRow(_grid, 2); root.Children.Add(_grid); var footer = new Grid { Margin = new Thickness(0, 6, 0, 0) }; footer.ColumnDefinitions.Add(new ColumnDefinition()); footer.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto }); footer.Children.Add(_status); var close = Button("Tutup"); close.Click += (_, _) => CloseRequested?.Invoke(this, EventArgs.Empty); Grid.SetColumn(close, 1); footer.Children.Add(close); Grid.SetRow(footer, 3); root.Children.Add(footer); return root;
    }
    private async Task LoadWarehousesAsync() { try { var rows = await _api.GetInventoryWarehousesAsync(false); _warehouse.ItemsSource = new[] { new InventoryWarehouseDto("", "Semua Gudang", false, true, 0) }.Concat(rows).ToList(); _warehouse.SelectedIndex = 0; } catch { } }
    private async Task ReloadAsync()
    {
        try
        {
            IsEnabled = false; var from = DateOnly.FromDateTime(_from.SelectedDate ?? DateTime.Today); var to = DateOnly.FromDateTime(_to.SelectedDate ?? DateTime.Today); var warehouse = _warehouse.SelectedValue?.ToString(); object report;
            if (IsPrice) report = await _api.GetInventoryPriceReportAsync(_query.Text);
            else if (IsHistory) report = await _api.GetInventoryPriceHistoryAsync(HistoryType(), from, to, _query.Text);
            else if (IsTransaction) report = await _api.GetInventoryTransactionReportAsync(from, to, TransactionType(), _query.Text);
            else if (_kind is InventoryReportKind.StockCard or InventoryReportKind.StockCardValue) report = await _api.GetInventoryStockCardAsync(from, to, _query.Text, warehouse, _kind == InventoryReportKind.StockCardValue);
            else if (_kind is InventoryReportKind.DailyEndingStock or InventoryReportKind.DailyOutbound) report = await _api.GetInventoryDailyActivityAsync(from, to, _query.Text, warehouse);
            else if (_kind == InventoryReportKind.Turnover) report = await _api.GetInventoryTurnoverAsync(from, to, _query.Text, warehouse);
            else report = await _api.GetInventoryValuationAsync(_query.Text, warehouse, ValuationMode());
            var rows = report.GetType().GetProperty("Rows")?.GetValue(report) as System.Collections.IEnumerable; var totals = report.GetType().GetProperty("Totals")?.GetValue(report);
            if(rows is not null&&_kind is InventoryReportKind.OpeningBalance or InventoryReportKind.Adjustments){var adjustmentRows=rows.Cast<InventoryTransactionReportRowDto>();rows=(_kind==InventoryReportKind.OpeningBalance?adjustmentRows.Where(x=>x.Counterparty?.Contains("Saldo Awal",StringComparison.OrdinalIgnoreCase)==true):adjustmentRows.Where(x=>x.Counterparty?.Contains("Saldo Awal",StringComparison.OrdinalIgnoreCase)!=true)).ToList();}
            _grid.ItemsSource = rows; _status.Text = FormatTotals(totals); if (_kind == InventoryReportKind.DailyOutbound) HideColumns("QuantityIn", "EndingQuantity", "AverageCost", "EndingValue");
        }
        catch (Exception exception) { _status.Text = exception.Message; }
        finally { IsEnabled = true; }
    }
    private void HideColumns(params string[] names) { _grid.UpdateLayout(); foreach (var column in _grid.Columns) if (column.SortMemberPath is not null && names.Contains(column.SortMemberPath)) column.Visibility = Visibility.Collapsed; }
    private void CopyCsv()
    {
        if (_grid.ItemsSource is not System.Collections.IEnumerable rows) return; var items = rows.Cast<object>().ToList(); if (items.Count == 0) return; var properties = items[0].GetType().GetProperties(BindingFlags.Instance | BindingFlags.Public); var csv = new StringBuilder(); csv.AppendLine(string.Join(';', properties.Select(x => Csv(x.Name)))); foreach (var row in items) csv.AppendLine(string.Join(';', properties.Select(x => Csv(x.GetValue(row)?.ToString() ?? "")))); Clipboard.SetText(csv.ToString()); _status.Text = $"{items.Count:N0} baris disalin sebagai CSV.";
    }
    private void Print() => ReportGridTools.PrintDataGrid(_grid, ReportTitle);
    private void FormatGeneratedColumn(object? sender, DataGridAutoGeneratingColumnEventArgs e)
    {
        if (_kind != InventoryReportKind.StockCardValue ||
            !string.Equals(e.PropertyName, nameof(InventoryStockCardRowDto.UnitCost), StringComparison.Ordinal) ||
            e.Column is not DataGridTextColumn column)
            return;

        column.Binding = new Binding(e.PropertyName)
        {
            StringFormat = "N2",
            ConverterCulture = IndonesianCulture
        };
    }
    private void SizeGeneratedColumns() { foreach (var column in _grid.Columns) { var header = column.Header?.ToString() ?? ""; column.MinWidth = 76; column.Width = header.Contains("Name", StringComparison.OrdinalIgnoreCase) || header.Contains("Description", StringComparison.OrdinalIgnoreCase) || header.Contains("Counterparty", StringComparison.OrdinalIgnoreCase) ? 190 : 105; } }
    private bool IsPrice => _kind <= InventoryReportKind.Labels; private bool IsHistory => _kind is >= InventoryReportKind.PurchasePriceHistory and <= InventoryReportKind.StandardCostHistory; private bool IsTransaction => _kind is >= InventoryReportKind.Transactions and <= InventoryReportKind.MbapReceives;
    private string HistoryType() => _kind switch { InventoryReportKind.PurchasePriceHistory => "PURCHASE", InventoryReportKind.PurchaseReturnPriceHistory => "PURCHASE_RETURN", InventoryReportKind.SalePriceHistory => "SALE", InventoryReportKind.SaleReturnPriceHistory => "SALE_RETURN", _ => "STANDARD_COST" };
    private string? TransactionType() => _kind switch { InventoryReportKind.Transfers => "TRANSFER", InventoryReportKind.StockCounts => "STOCK_COUNT", InventoryReportKind.MbapSends => "MBAP_SEND", InventoryReportKind.MbapReceives => "MBAP_RECEIVE", InventoryReportKind.AllAdjustments or InventoryReportKind.OpeningBalance or InventoryReportKind.Adjustments => "ADJUSTMENT", _ => null };
    private string ValuationMode() => _kind switch { InventoryReportKind.ValuationNoCost => "NO_COST", InventoryReportKind.MinimumStock => "MIN", InventoryReportKind.MaximumStock => "MAX", InventoryReportKind.StockLimits => "LIMITS", _ => "ALL" };
    private static string FormatTotals(object? totals) { if (totals is null) return "Laporan siap."; var type = totals.GetType(); string Value(string name) => type.GetProperty(name)?.GetValue(totals) is decimal value ? value.ToString("N2") : type.GetProperty(name)?.GetValue(totals)?.ToString() ?? "0"; return $"{Value("RowCount")} baris | Masuk {Value("QuantityIn")} | Keluar {Value("QuantityOut")} | Saldo {Value("EndingQuantity")} | Nilai {Value("InventoryValue")} | Transaksi {Value("TransactionAmount")}"; }
    private static string Csv(string value) => $"\"{value.Replace("\"", "\"\"")}\""; private static TextBlock Label(string text) => new() { Text = text, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(8, 0, 5, 0) }; private static Button Button(string text) => new() { Content = text, Width = 90, Margin = new Thickness(5, 0, 0, 0) }; private static SolidColorBrush Brush(string value) => new((Color)ColorConverter.ConvertFromString(value));
    private static string TitleFor(InventoryReportKind kind) => kind switch
    {
        InventoryReportKind.RetailPrices => "Laporan Daftar Harga Barang Eceran", InventoryReportKind.TierPrices => "Laporan Harga Eceran, Grosir & Partai", InventoryReportKind.CompletePrices => "Laporan Harga Barang Lengkap", InventoryReportKind.PriceAnalysis => "Analisa Harga Jual Barang", InventoryReportKind.Labels => "Cetak Label Barang",
        InventoryReportKind.PurchasePriceHistory => "Histori Harga Beli per Supplier", InventoryReportKind.PurchaseReturnPriceHistory => "Histori Harga Retur Beli per Supplier", InventoryReportKind.SalePriceHistory => "Histori Harga Jual per Customer", InventoryReportKind.SaleReturnPriceHistory => "Histori Harga Retur Jual per Customer", InventoryReportKind.StandardCostHistory => "Histori HPP Standar",
        InventoryReportKind.Transactions => "Laporan Transaksi Persediaan", InventoryReportKind.Transfers => "Laporan Mutasi Barang", InventoryReportKind.AllAdjustments => "Penyesuaian Persediaan Semua", InventoryReportKind.OpeningBalance => "Laporan Saldo Awal", InventoryReportKind.Adjustments => "Laporan Penyesuaian", InventoryReportKind.StockCounts => "Laporan Stok Fisik", InventoryReportKind.MbapSends => "Laporan MBAP Kirim", InventoryReportKind.MbapReceives => "Laporan MBAP Terima",
        InventoryReportKind.StockCard => "Kartu Stok tanpa Nilai", InventoryReportKind.StockCardValue => "Kartu Stok dengan Nilai", InventoryReportKind.Valuation => "Persediaan Lengkap", InventoryReportKind.ValuationNoCost => "Persediaan tanpa HPP", InventoryReportKind.MinimumStock => "Persediaan Minimum Stok", InventoryReportKind.MaximumStock => "Persediaan Maximum Stok", InventoryReportKind.DailyEndingStock => "Stok Akhir per Hari", InventoryReportKind.DailyOutbound => "Barang Keluar per Hari", InventoryReportKind.Turnover => "Tingkat Pergerakan Barang", _ => "Batas Stok"
    };
}
